import requests
import ipaddress
import socket
from django.conf import settings
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from urllib.parse import urlparse
import ldclient
from ldclient.config import Config

# LaunchDarkly client initialization
ldclient.set_config(Config(settings.LAUNCHDARKLY_SDK_KEY))
ld_client = ldclient.get()


def resolve_and_validate(url):
    """Resolve hostname and check if it points to internal network.
    NOTE: This check is vulnerable to DNS rebinding - the resolved IP
    may differ between validation time and request time."""
    parsed = urlparse(url)
    hostname = parsed.hostname
    port = parsed.port or (443 if parsed.scheme == 'https' else 80)

    try:
        resolved_ip = socket.gethostbyname(hostname)
        ip_obj = ipaddress.ip_address(resolved_ip)

        if ip_obj.is_private or ip_obj.is_loopback or ip_obj.is_link_local:
            return None, "Resolved to internal IP address"

        return resolved_ip, None
    except socket.gaierror:
        return None, "DNS resolution failed"


def fetch_url_with_rebind_protection(url):
    """Fetch URL with DNS pinning to prevent rebinding.
    Uses socket-level connection to the pre-resolved IP."""
    parsed = urlparse(url)
    hostname = parsed.hostname
    resolved_ip, error = resolve_and_validate(url)

    if error:
        return None, error

    # Pin the DNS resolution by connecting directly to resolved IP
    # and setting Host header
    pinned_url = url.replace(hostname, resolved_ip)
    headers = {'Host': hostname}

    try:
        resp = requests.get(pinned_url, headers=headers, timeout=5, verify=False)
        return resp.text, None
    except requests.RequestException as e:
        return None, str(e)


def fetch_url_naive(url):
    """Simple URL fetch - vulnerable to DNS rebinding between
    resolve_and_validate() check and actual request."""
    resolved_ip, error = resolve_and_validate(url)
    if error:
        return None, error

    # TOCTOU gap: DNS may resolve differently now
    try:
        resp = requests.get(url, timeout=5)
        return resp.text, None
    except requests.RequestException as e:
        return None, str(e)


class WebhookProxyView(APIView):
    """Proxy endpoint for validating and fetching webhook URLs
    provided by tenants during integration setup."""

    def post(self, request):
        url = request.data.get('url')
        if not url:
            return Response(
                {'error': 'url is required'},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Validate URL scheme
        parsed = urlparse(url)
        if parsed.scheme not in ('http', 'https'):
            return Response(
                {'error': 'Only http/https schemes allowed'},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Feature flag controls which fetch implementation to use
        user_context = {
            'key': str(request.user.id) if request.user.is_authenticated else 'anonymous',
            'custom': {
                'tenant_id': request.headers.get('X-Tenant-ID', 'default'),
                'plan': request.headers.get('X-Plan-Tier', 'free')
            }
        }

        use_dns_pinning = ld_client.variation(
            'webhook-proxy-dns-pinning',
            user_context,
            False  # default: use naive implementation
        )

        if use_dns_pinning:
            content, error = fetch_url_with_rebind_protection(url)
        else:
            content, error = fetch_url_naive(url)

        if error:
            return Response(
                {'error': error},
                status=status.HTTP_422_UNPROCESSABLE_ENTITY
            )

        return Response({
            'status': 'reachable',
            'content_length': len(content),
            'preview': content[:256]
        })
